test('removeLine returns NO_LINES if removing the last line', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  assert.deepEqual(removeLine(r1.value, 'DEV-HOUR'), {
    ok: false,
    error: 'NO_LINES',
  });
});

test('removeLine rejects non-draft invoices', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'DES-HOUR', qty: 5 },
