  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'DES-HOUR', qty: 5 },
    ],
  });

  const invoiceCopy = JSON.parse(JSON.stringify(r1.value));

  removeLine(r1.value, 'DES-HOUR');

  assert.deepEqual(r1.value, invoiceCopy);
});

test('removeLine works with three lines', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'COPY-HOUR', qty: 3 },
